      const products = await prisma2.product.findMany({
        where: {
          isArchived: false
          // Filter out archived products
        },
        include: {
          category: true,
          variants: {
            include: {
              attributeValues: { include: { attribute: { select: { name: true } } } }
            }
          },
          images: {
            take: 1,
            orderBy: { order: "asc" }
          }
        }
      });
      let totalValue = 0;
      let totalItems = 0;
      let lowStockCount = 0;
      let outOfStockCount = 0;
