  { name: "general", color: "#64748b" },
  { name: "antibiotic", color: "#8b5cf6" },
  { name: "antiparasitic", color: "#0ea5e9" },
  { name: "vaccine", color: "#10b981" },
  { name: "anesthetic", color: "#f59e0b" },
  { name: "analgesic", color: "#ef4444" },
  { name: "supplement", color: "#ec4899" }
